{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "The most similar analogue was detected in mouse brain after oral gavage dosing, directly demonstrating in vivo BBB crossing and meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bupropion, a close analogue, showed rapid equilibration across the BBB with a Kp,uu of 1.9 by quantitative microdialysis, supporting meaningful unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "L-365,260 showed very low BBB permeability in mouse PET/biodistribution studies, arguing against CNS access, though this conflicts with another L-365,260 penetration record.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally similar analogues with direct systemic in vivo CNS measurements show meaningful brain access, including oral brain detection, Kp,uu >1, and brain/plasma ratios >1. The negative L-365,260 PET/biodistribution result is offset by a conflicting positive L-365,260 penetration record and lower overall weight, so the prediction is pass.",
  "evidence_gaps": [
    "Conflicting L-365,260 evidence: one record reports ~0.5% brain penetration in mice, while PET/biodistribution records report very low BBB permeability; unresolved.",
    "No direct query-specific data; predictions rely on analogues with moderate Morgan similarity (0.26-0.38).",
    "The negative YF 476 result is a single low-similarity rat radioactivity measurement with limited transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

